for idx, item in enumerate(mus_100):
    if len([x for x in cam_final_items if x['subject'] == 'cam_music']) >= 100:
        break
    grade = (idx % 6) + 1
    t, q, opts, c, exp, h, diff = item
    add_q(f"cam-mus-sup-{idx+1:03d}", "cam_music", grade, t, q, opts, c, exp, h, diff)

